package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The people of a sheet's whole tree (its root and all the root's descendants) whose name or an alias
 * contains a text, case ignored, each with their due-total as their own sheet shows it now.
 */
@Service
public class TreeSearch {

    /** A person found: their sheet, name, grade in force on their sheet's today and due-total (null when n/a). */
    public record Found(String sheetId, String name, String grade, BigDecimal dueTotal) {
    }

    private final SheetService sheets;
    private final PersonRepository people;
    private final Rollups rollups;

    public TreeSearch(SheetService sheets, PersonRepository people, Rollups rollups) {
        this.sheets = sheets;
        this.people = people;
        this.rollups = rollups;
    }

    /** The people found: this sheet's first in list order, then the other sheets' by sheet id. */
    @Transactional(readOnly = true)
    public List<Found> search(String sheetId, String text) {
        String key = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
        List<String> others = new ArrayList<>(sheets.tree(sheetId));
        others.remove(sheetId);
        others.sort(null);
        List<String> order = new ArrayList<>();
        order.add(sheetId);
        order.addAll(others);
        List<Found> found = new ArrayList<>();
        for (String id : order) {
            Rollups.Rollup rollup = rollups.take(id);
            LocalDate today = sheets.today(id);
            for (Person person : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
                if (matches(person, key)) {
                    Rollups.Figures figures = rollup.people().get(person.getId());
                    found.add(new Found(id, person.getName(), person.gradeOn(today), figures == null ? null : figures.dueTotal()));
                }
            }
        }
        return found;
    }

    private static boolean matches(Person person, String key) {
        if (person.getName().toLowerCase(Locale.ROOT).contains(key)) {
            return true;
        }
        return person.getAliases().stream().anyMatch(alias -> alias.toLowerCase(Locale.ROOT).contains(key));
    }
}
package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/sheets")
@Validated
public class TreeSearchController {

    /** A person found as the screen shows them: their sheet, name, grade in force on their sheet's today
     * and due-total (two decimals, or n/a). */
    public record FoundView(String sheetId, String name, String grade, String dueTotal) {
    }

    private final TreeSearch search;

    public TreeSearchController(TreeSearch search) {
        this.search = search;
    }

    /** The people over the sheet's whole tree whose name or an alias contains the text, case ignored. */
    @GetMapping("/{id}/search")
    public List<FoundView> search(
            @PathVariable @NotBlank @Size(max = 64) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestParam(defaultValue = "") @Size(max = 200) String text) {
        return search.search(id, text).stream()
                .map(found -> new FoundView(found.sheetId(), found.name(), found.grade(), Rollups.shown(found.dueTotal())))
                .toList();
    }
}

